<?php
require_role(['admin']);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']);$email=trim($_POST['email']);$password=$_POST['password'];$roleNew=$_POST['role'];$club=($_POST['club_id']??'')!==''?(int)$_POST['club_id']:null;$swimmer=($_POST['swimmer_id']??'')!==''?(int)$_POST['swimmer_id']:null;
$roles=['admin','organisateur','club','officiel','nageur','entraineur'];if(!in_array($roleNew,$roles,true)||strlen($password)<10){flash('Rôle invalide ou mot de passe trop court (10 caractères minimum).','error');}else{$s=db()->prepare('INSERT INTO users(name,email,password,role,club_id,swimmer_id) VALUES(?,?,?,?,?,?)');try{$s->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$roleNew,$club,$swimmer]);flash('Utilisateur créé.');}catch(Throwable $e){flash('Création impossible : e-mail déjà utilisé ou association invalide.','error');}}redirect('index.php?page=users');}
?>
<div class="grid2"><section class="panel"><h3>Créer un utilisateur</h3><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Nom</label><input name="name" required><label>E-mail</label><input type="email" name="email" required><label>Mot de passe initial</label><input type="password" name="password" minlength="10" required><label>Rôle</label><select name="role"><?php foreach(['admin','organisateur','club','officiel','nageur','entraineur'] as $r):?><option><?=e($r)?></option><?php endforeach;?></select><label>Club associé (si nécessaire)</label><select name="club_id"><option value="">Aucun</option><?php foreach(db()->query('SELECT id,name FROM clubs') as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select><label>Profil nageur (pour rôle nageur)</label><select name="swimmer_id"><option value="">Aucun</option><?php foreach(db()->query('SELECT id,first_name,last_name FROM swimmers') as $s):?><option value="<?=$s['id']?>"><?=e($s['first_name'].' '.$s['last_name'])?></option><?php endforeach;?></select><button class="btn primary">Créer le compte</button></form></section><section class="panel"><h3>Comptes existants</h3><div class="table-wrap"><table><tr><th>Nom</th><th>E-mail</th><th>Rôle</th><th>Club</th></tr><?php foreach(db()->query('SELECT u.*,c.name club FROM users u LEFT JOIN clubs c ON c.id=u.club_id ORDER BY u.id') as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['role'])?></td><td><?=e($r['club']??'—')?></td></tr><?php endforeach;?></table></div></section></div>